/**
 * Writes `va-runtime.generated.ts` from a fresh bundle of the runtime: run it after changing the
 * runtime, with `pnpm exec tsx packages/app/src/explorables/runtime/generate.ts`, and commit the file.
 */
import { writeFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { bundleRuntime } from './bundle';

/** The generated module's text for a bundle. */
export function runtimeModule(code: string): string {
  return [
    '// Generated by generate.ts from the `va` runtime (va.ts, still.ts); do not edit.',
    '// prettier-ignore',
    `export const VA_RUNTIME: string = ${JSON.stringify(code)};`,
    '',
  ].join('\n');
}

export const GENERATED = fileURLToPath(new URL('./va-runtime.generated.ts', import.meta.url));

if (process.argv[1] === fileURLToPath(import.meta.url)) {
  const { code } = await bundleRuntime();
  writeFileSync(GENERATED, runtimeModule(code));
  console.log(`Wrote ${GENERATED}: ${code.length} characters.`);
}
